'use strict';
navOwner.splice(1,0,['mycards','card','بطاقاتي']);
const launchedOwner=ownerHTML;
ownerHTML=function(){if(view!=='mycards')return launchedOwner();const active=db.shops.filter(s=>!s.archivedAt),deleted=db.shops.filter(s=>s.archivedAt);return head('برامج نشاطك','بطاقاتي','لكل بطاقة عملاؤها ورصيدها وسجل عملياتها.',`<button class="btn primary" data-action="new-program" ${active.length>=RijaaPlans.forAccount(shopAccount()).cards?'disabled':''}>${icon('plus')} بطاقة جديدة</button>`)+`<div class="admin-shops">${active.map(s=>`<article class="panel"><h3>${esc(s.card.title||s.name||'بطاقة الولاء')}</h3>${cardHTML(s.card)}<p class="sub mt">${fmt(s.members.length)} عميل · ${esc(programSummary(s.card))}</p><div class="actions mt"><button class="btn primary" data-action="edit-program" data-id="${esc(s.id)}">تعديل البطاقة</button><button class="btn secondary" data-action="program-customers" data-id="${esc(s.id)}">العملاء (${fmt(s.members.length)})</button><button class="btn quiet" data-action="delete-program" data-id="${esc(s.id)}">حذف البطاقة</button></div></article>`).join('')}</div>${!active.length?'<div class="notice">لا توجد بطاقات حاليًا. أنشئ بطاقة جديدة لبرنامجك.</div>':''}${deleted.length?`<details class="card-option-panel mt"><summary>البطاقات المحذوفة (${fmt(deleted.length)})</summary><p class="sub">يمكن استعادتها مع العملاء والأرصدة وسجل العمليات.</p>${deleted.map(s=>`<div class="actions mt"><strong>${esc(s.card.title||s.name||'بطاقة الولاء')}</strong><button class="btn secondary small" data-action="restore-program" data-id="${esc(s.id)}">استعادة البطاقة</button></div>`).join('')}</details>`:''}`;};
const launchedHome=homeHTML;
homeHTML=function(){const html=launchedHome();const wrapper=document.createElement('div');wrapper.innerHTML=html;const cards=[{...templates[0],program:{type:'visits'}},{...templates[1],reward:'خصم على الغسيل',program:{type:'discount',discountType:'percent',discountValue:20}},{...templates[3],name:'حلاق الحي',reward:'حلاقة مجانية',program:{type:'points',pointsPerVisit:10,pointsCost:100}}];wrapper.querySelector('.showcase').innerHTML=cards.map((c,i)=>`<div class="showcase-item showcase-${i}">${cardHTML(c)}<p>${['بطاقة الزيارات','بطاقة الخصومات','بطاقة النقاط'][i]}</p></div>`).join('');wrapper.querySelector('.landing-intro>p').textContent='زيارات، خصومات أو نقاط. صمّم برنامج ولاء باسم نشاطك، وخلّ فريقك يسجل الزيارات بسهولة.';wrapper.querySelector('.landing-kicker').textContent='كل زيارة، فرصة للرجعة.';return wrapper.innerHTML;};
const launchedLogin=loginHTML;
loginHTML=function(){if(!/^\/admin\/?$/i.test(location.pathname))return launchedLogin();const wrapper=document.createElement('div');wrapper.innerHTML=launchedLogin();wrapper.querySelector('h1').textContent='دخول إدارة رِجعة';wrapper.querySelector('.auth-panel h2').textContent='إدارة المنصة';wrapper.querySelector('.segmented')?.remove();wrapper.querySelector('.new-business-option')?.remove();wrapper.querySelectorAll('[name=name],[name=business]').forEach(e=>e.closest('label').remove());wrapper.querySelector('.auth-panel>.sub').textContent='الدخول مخصص لرقم الإدارة المعتمد، برمز تحقق عبر رسالة نصية.';return wrapper.innerHTML;};
mutationActions.add('new-program');mutationActions.add('confirm-delete-program');mutationActions.add('restore-program');
window.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(!['new-program','select-program','edit-program','delete-program','confirm-delete-program','restore-program','program-customers','back-admin'].includes(a))return;e.preventDefault();e.stopImmediatePropagation();try{if(a==='back-admin'){role='admin';view='accounts';render();return;}if(a==='delete-program'){const selected=db.shops.find(s=>s.id===b.dataset.id);modal('حذف البطاقة',`<p>سيتم إيقاف بطاقة ${esc(selected.card.title||selected.name)} وإخفاؤها من البطاقات النشطة. يُحفظ العملاء والأرصدة ويمكن استعادة البطاقة لاحقًا.</p>` ,`<button class="btn secondary" data-action="close-modal">إلغاء</button><button class="btn danger" data-action="confirm-delete-program" data-id="${esc(selected.id)}">حذف البطاقة</button>`);return;}if(['confirm-delete-program','restore-program'].includes(a)){if(!canOperate())throw Error('يلزم تفعيل الاشتراك.');if(serverMode)await serverCommand({action:a==='restore-program'?'restore-program':'delete-program',shop:b.dataset.id},{redraw:false});else{const selected=db.shops.find(s=>s.id===b.dataset.id);if(a==='restore-program')delete selected.archivedAt;else selected.archivedAt=Date.now();save();}document.querySelector('#modal').close();view='mycards';draft=null;render();toast(a==='restore-program'?'تمت استعادة البطاقة.':'تم حذف البطاقة؛ يمكنك استعادتها.');return;}if(a==='new-program'){if(!canOperate())throw Error('يلزم تفعيل الاشتراك أولًا.');if(db.shops.filter(s=>!s.archivedAt).length>=RijaaPlans.forAccount(shopAccount()).cards)throw Error('وصلت إلى حد بطاقات باقتك.');modal('بطاقة ولاء جديدة',`<form id="program-form"><label class="field"><span>اسم البطاقة</span><input class="input" name="name" maxlength="36" required></label><label class="field"><span>نظام الولاء</span><select name="type"><option value="visits">زيارات ومكافآت</option><option value="discount">زيارات وخصومات</option><option value="points">نقاط</option></select></label><p id="program-error" class="error"></p><button class="btn primary full">إنشاء البطاقة</button></form>`);return;}db.shop=b.dataset.id;draft=null;lastTx=null;view=a==='program-customers'?'customers':a==='edit-program'?'design':'overview';if(a==='edit-program')draft=structuredClone(shop().card);render();}catch(error){toast(error.message);}},true);
window.addEventListener('submit',async e=>{if(e.target.getAttribute("id")!=='program-form')return;e.preventDefault();e.stopImmediatePropagation();const d=new FormData(e.target);try{if(!serverMode)throw Error('إنشاء البطاقات متاح في نسخة التشغيل.');await serverCommand({action:'create-program',name:d.get('name'),type:d.get('type')});document.querySelector('#modal').close();view='design';draft=structuredClone(shop().card);render();}catch(error){document.querySelector('#program-error').textContent=error.message;}},true);
const launchedRender=render;
render=function(){launchedRender();if(!serverMode)return;document.querySelectorAll('.notice').forEach(el=>{if(/هذه رحلة تجريبية|رابط التجربة يعرض/.test(el.textContent))el.remove();});document.querySelectorAll('[data-action=choose-client],[data-action=client-to-staff],[data-action=existing-client],.join-layout [data-action=role]').forEach(el=>el.remove());if(principal?.kind==='admin'&&role==='owner'){const b=document.createElement('button');b.className='btn secondary small';b.dataset.action='back-admin';b.textContent='العودة للإدارة';document.querySelector('.topbar')?.append(b);}if(role==='staff'&&db.shops.length>1){const select=document.createElement('select');select.className='input';select.setAttribute('aria-label','بطاقة الولاء');select.innerHTML=db.shops.filter(s=>!s.archivedAt).map(s=>`<option value="${esc(s.id)}" ${s.id===db.shop?'selected':''}>${esc(s.card.name||s.card.title||s.name||'بطاقة الولاء')}</option>`).join('');select.onchange=()=>{db.shop=select.value;lastTx=null;render();};document.querySelector('.main')?.prepend(select);}};
render();
